package com.shipflow.order.application;
import com.shipflow.order.api.model.*; import com.shipflow.order.domain.model.ShipmentOrder; import com.shipflow.order.mapper.ShipmentOrderMapper; import org.springframework.stereotype.Service; import java.time.ZoneOffset; import java.util.List;
@Service public class ShipmentOrderQueryApplicationService { private final ShipmentOrderMapper mapper; public ShipmentOrderQueryApplicationService(ShipmentOrderMapper mapper){this.mapper=mapper;}
 public ShipmentOrderResponse get(Long tenant,Long id){return response(require(mapper.findById(tenant,id)));}
 public ShipmentOrderPageResponse list(Long tenant,String status,Long storeId,int page,int pageSize){if(page<1||pageSize<1||pageSize>100)throw new ShipmentOrderException("COMMON-1001",400); long total=mapper.count(tenant,status,storeId);return new ShipmentOrderPageResponse(page,pageSize,(total+pageSize-1)/pageSize,total,mapper.findPage(tenant,status,storeId,(page-1)*pageSize,pageSize).stream().map(this::response).toList());}
 ShipmentOrder require(ShipmentOrder order){if(order==null)throw new ShipmentOrderException("COMMON-1006",404);return order;} ShipmentOrderResponse response(ShipmentOrder o){return new ShipmentOrderResponse(o.id(),o.orderNo(),o.quoteId(),o.currentStatus(),o.estimatedFee(),o.currency(),o.chargeableWeight(),o.version(),o.createdAt().atOffset(ZoneOffset.UTC));}}
